const TIER_RANK = { free: 0, pro: 1, enterprise: 2 };

function makeEnterpriseSsoRule() {
  return {
    name: "enterprise-sso",
    applies(ctx) {
      return TIER_RANK[ctx.plan.tier] >= TIER_RANK.enterprise;
    },
  };
}

